public int anagram(String s) {
    int n = s.length();
    if (n % 2 != 0) return -1;
    char[] a = s.substring(0, n / 2).toCharArray();
    char[] b = s.substring(n / 2).toCharArray();
    Arrays.sort(a);
    Arrays.sort(b);
    int[] countA = new int[26];
    int[] countB = new int[26];
    for (char c : a) countA[c - 'a']++;
    for (char c : b) countB[c - 'a']++;
    int changes = 0;
    for (int i = 0; i < 26; i++) {
        if (countA[i] > countB[i]) changes += countA[i] - countB[i];
    }
    return changes;
}

