def anagram(self, s: str) -> int:
    n = len(s)
    if n % 2 != 0:
        return -1
    a = sorted(s[:n // 2])
    b = sorted(s[n // 2:])
    from collections import Counter
    count_a, count_b = Counter(a), Counter(b)
    return sum(max(0, count_a[c] - count_b[c]) for c in count_a)

