public int anagram(String s) {
    int n = s.length();
    if (n % 2 != 0) return -1;
    int[] balance = new int[26];
    int half = n / 2;
    for (int i = 0; i < half; i++) balance[s.charAt(i) - 'a']++;
    for (int i = half; i < n; i++) balance[s.charAt(i) - 'a']--;
    int changes = 0;
    for (int c : balance) {
        if (c > 0) changes += c;
    }
    return changes;
}

