def anagram(self, s: str) -> int:
    n = len(s)
    if n % 2 != 0:
        return -1
    balance = [0] * 26
    half = n // 2
    for ch in s[:half]:
        balance[ord(ch) - 97] += 1
    for ch in s[half:]:
        balance[ord(ch) - 97] -= 1
    return sum(c for c in balance if c > 0)

